          "type": "p",
          "text": "“这一发现几乎属于我所说的偶然发现（Serendipity）之类，是一个意味深长的词……此前我曾读过一则名为《赛伦迪普（今斯里兰卡）的三王子》的滑稽童话。那几位王子在旅途中总是凭借偶然与智慧有所发现。”"
