          "type": "p",
          "text": "“兄弟们依次陈述如下……它的右眼必定是瞎的。因为左边的草并不比右边的更茂密，骆驼却只吃了左边的草。这匹骆驼的牙齿不好。因为它吃草的方式表明了牙齿不好。这匹骆驼是瘸腿的。因为只清楚地留下了三个脚印，第四个脚印则呈拖拽的痕迹……骆驼走过的痕迹一侧有许多蚂蚁，由此推测那一侧驮的是满载的黄油；沿着另一侧聚集了许多苍蝇，由此推测那一侧驮的是蜂蜜。注意到骆驼跪下之处附近的脚印，发现了少许女人的尿迹，由此推测骆驼上必定驮着一个女人……于是第三位王子做出结论。他推测那女人已经怀孕了。因为附近的手印看起来是她小便之后，用手支撑自己站起来时留下的。”"
