          "type": "p",
          "text": "'我、此地、此刻'的塞伦迪皮蒂理论，与共通模式一样，是从重新厘定围绕共感的误解与理论出发的。虽说共感曾为四大圣人所强调，但在今天，依据近代科学的传统，它却成为被回避的对象。人们虽已认识到塞伦迪皮蒂的重要性，塞伦迪皮蒂却未能得到正式的理论化，其决定性原因正在于对共感的误解。"
