          "text": "西方同样在延续地水火风传统的神秘主义传统中，承继了类比思维体系。地水火风的神秘主义传统，自俄耳甫斯、毕达哥拉斯发端，其背景也浓厚地渗透于柏拉图、亚里士多德的著作之中。西方的类比思维体现于共时性思维之中。到了现代，将共时性与类比思维加以学问化的代表人物，当推荣格与巴什拉。[56] 荣格反对弗洛伊德基于因果论的精神分析，创立了以共时性理论为基础的分析心理学。例如，一个精神上有困扰的人，某天上班途中发现了平日从未见过的黄色汽车和鸟儿，或是在梦中做了一个特别的梦，这类梦境与新发现往往会为其自身所面临的问题提供深刻的答案。实际上，被称为塞伦迪皮蒂的阿基米德的发现、苯环的发现，都可以用荣格的共时性原理来加以解释。"
