          "text": "济州岛运用新儒家思想，很早便具有将济州视为宇宙之象征的科学思维。汉拿山之名被解读为“牵引宇宙的山峰”，[72]石头爷爷（돌하르방）则可被解读为守护宇宙的守护神，济州岛拥有超越以半岛为中心的自然观的自然哲学。如石头爷爷一般，成对矗立于济州每一处居所的守护石像，据说与中国汉代时北极星周围的两颗星相对应，这可以说是曾将济州视为北极星，即视济州为宇宙中心的遗迹。[73] 所谓“辅弼”，正是这北极星旁两颗星的名字。济州的“오름”（火山丘）也如新儒家的世界观、即《周易》之数一般，共有象征一年的360座。据说当时朝鲜的郡守也是360人。可以说，济州自古便以“我、此地、此刻”为中心而思考。也有人批评说，“济州（濟州）”这一名称，过去是站在陆地的立场上，取“水外之地”之意而使用的、并非具有主体性的名字。[74] 然而，若将济州岛视为宇宙的缩影，那么“济州”之名便含有“济度宇宙（拯救宇宙）”之意。实际上，济州是韩国国内唯一拥有“雪门大婆婆（설문대할망）”这一开天辟地巫歌主人公的地方。[75] 而以《朝鲜巫俗考》闻名的李能和则认为，三姓穴中的“乙那（을라）”意为“王”。[76]"
