          "text": "蚕也展现了济州在创意性方面的另一个特点。济州蚕的特别之处在于，与内陆的蚕不同，它并非只经三眠，而是要经历四眠、五眠，显得更加从容。内陆的蚕大多在化蝶之前只经三眠。济州蚕之所以以品质优良著称，就在于比内陆蚕多眠一两次。或许正因如此，最近西归浦市大静邑武陵里的农业组合法人「乡村」正在复原60~70年代曾在济州盛行、如今已消失的养蚕产业，将其发展为新的特色产业，成为话题。"
