          "text": "右图是将与七相对应的三承奶奶传说中，旧三承奶奶背着차롱（竹篮）离去的场景加以戏剧化呈现的照片。[71] 三承奶奶是济州岛对三神奶奶的称呼，与陆地不同之处在于，这里存在如释迦与弥勒对决一般的旧三承奶奶与新三承奶奶之间的对立。由于旧三承奶奶要离去，所以须在其加害之前赠以차롱（竹篮）加以安抚。三神与七星所司之职，与陆地相同：三神掌管出生与死亡，七星则掌管出生之后的成长。"
