              "text": "欧洲空间局（ESA）与俄罗斯、中国为了解长期火星旅行对人体产生的影响，共同推进了“火星500（Mars500）”项目。美国国家航空航天局（NASA）计划于2035年实施载人火星探测。往返火星所需时间估计约为520天。参与该项目的6名宇航员，在俄罗斯莫斯科附近搭建的飞船模型中被隔离了520天，直到2011年11月才第一次呼吸到外界空气。宾夕法尼亚大学医学院的研究团队在发表于《美国国家科学院院刊（PNAS）》的论文中指出，该项目参与者身上最显著的变化是运动量的减少。（《朝鲜日报》，2013年1月15日）"
